// Saved는 저장된 결과의 메타데이터입니다.
type Saved struct {
	ID        int64     `json:"id"`
	DBSeq     int64     `json:"db_seq"`
	DBName    string    `json:"db_name"`
	UserSeq   int64     `json:"user_seq"`
	UserName  string    `json:"user_name"`
