	CreatedAt time.Time `json:"created_at"`
}

// SavedPage는 페이지네이션된 저장 결과 목록입니다.
type SavedPage struct {
	Items  []Saved `json:"items"`
	Total  int64   `json:"total"`
	Limit  int     `json:"limit"`
	Offset int     `json:"offset"`
}

// Detail은 저장된 결과 본문(컬럼+행)입니다.
type Detail struct {
	Saved
	Columns []query.Column   `json:"columns"`
	Rows    []map[string]any `json:"rows"`
}

type storedResult struct {
	Columns []query.Column   `json:"columns"`
	Rows    []map[string]any `json:"rows"`
}

type Repository interface {
	InsertSavedResult(ctx context.Context, userID, dbSeq int64, sqlText, resultJSON string, rowCount int) (Saved, error)
	ListSavedResults(ctx context.Context, userID int64, admin bool, limit, offset int) ([]Saved, int64, error)
	GetSavedResult(ctx context.Context, id, userID int64, admin bool) (Saved, string, error)
	DeleteSavedResult(ctx context.Context, id, userID int64, admin bool) error
}

type Service struct {
	repository Repository
	executor   *query.Executor
}

func NewService(repository Repository, executor *query.Executor) *Service {
	return &Service{repository: repository, executor: executor}
}

